<script module>
	export const meta = { size: 'wide', title: 'The cone of two lens vectors, and its nearest point' };
	export { default as Key } from './fig-j-cone.key.svelte';
</script>

<script>
	// Figure: what is a cone of two vectors, and what is the nearest point of it?
	// Left, exact and in perspective: the plane spanned by two J-lens vectors v_s, v_u at one
	// depth (the disc: the span, which a subspace would fill), the cone of their nonnegative
	// combinations (hatched, covector ink: it is generated by covectors), the ghosts −v_s, −v_u
	// (in the span, not in the cone), an actual stream column x of the specimen above the
	// plane, its foot p (orthogonal projection), its nearest point x_J on the cone, the
	// remainder x − x_J (dashed), and the coordinates c_s, c_u of x_J along the edges.
	// Everything in the problem lies in the 3-dimensional subspace spanned by v_s, v_u and x,
	// so this drawing (an orthographic view of that subspace) loses nothing: every length in
	// it is a length in ℝ⁸.
	// Right: the 21 pairs (s, u) of characters as small cones in their own planes, each with
	// x's foot p (open) and nearest point (filled), and the share of ‖x‖² left over; the
	// J-space with k = 2 is the union of these 21 cones, and the distance to it is the
	// smallest of the 21 numbers (bold).
	// Data: v_a = lenses.vectors[a, :, j] (jspace.specimen); x = the specimen's stream at
	// depth j for the column (specimen.windowTrace: X0, Xmid, Xout), the export's column
	// n = t + (b−1)T with window b starting at corpus position b − 1. All fits computed here
	// (closed form for two vectors); they agree with the export's exact k = 2 fits.
	// Interaction: click a character to choose the column, a cell to choose the pair, a depth
	// on the track; drag the foot p within the plane (x keeps its height above the plane;
	// double-click or Escape returns it). Print: the stated column at its best pair.
	import { getContext } from 'svelte';
	import { measure } from '#figures/primitives/measure.js';
	import CorpusStrip from '#figures/primitives/CorpusStrip.svelte';
	import { fmt, fmtDense, showChar, clamp, layoutWidth } from '#figures/primitives/scales.js';
	import TickTrack from '../primitives/TickTrack.svelte';
	import ConeGlyph from '../primitives/ConeGlyph.svelte';
	import { at, depthLabel } from '../primitives/jdata.js';
	import { pairFit, nearestInPlane, axonometric, polarEdges } from '../primitives/cone.js';

	let { attrs = {}, mode = 'interactive' } = $props();
	const specimen = $derived(getContext('specimen')());
	const js = $derived(getContext('artifacts')()?.jspace?.specimen ?? null);
	const T = $derived(specimen.config.T);
	const V = $derived(specimen.config.V);
	const vocab = $derived(specimen.vocab);
	const interactive = $derived(mode !== 'print');

	// svelte-ignore state_referenced_locally
	let start = $state(clamp((+attrs.window || 1) - 1, 0, 9));
	// svelte-ignore state_referenced_locally
	let pos = $state(clamp((+attrs.column || 4) - 1, 0, 7));
	// svelte-ignore state_referenced_locally
	let depth = $state(attrs.depth != null ? clamp(Math.round(2 * +attrs.depth), 0, 2) : 1);
	let pairSet = $state(null); // [s, u] chosen by the reader; null = the best pair
	let drag = $state(null); // the dragged foot p (plane coordinates), or null
	let width = $state(868);
	const W = $derived(layoutWidth(width, mode, 330));
	const narrow = $derived(W < 720);

	// ── data ───────────────────────────────────────────────────────────────────────
	const tr = $derived(specimen.windowTrace(start));
	const x = $derived([tr.X0, tr.Xmid, tr.Xout][depth][pos]);
	const D = $derived(specimen.config.D);
	const vecs = $derived(js ? Array.from({ length: V }, (_, a) => Array.from({ length: D }, (_, q) => at(js.lenses.vectors, a, q, depth))) : []);
	const pairs = $derived.by(() => {
		const out = [];
		for (let u = 1; u < V; u++) for (let s = 0; s < u; s++) out.push({ s, u, ...pairFit(vecs[s], vecs[u], x) });
		return out;
	});
	const best = $derived(pairs.reduce((m, f) => (f.frac < m.frac ? f : m), pairs[0]));
	const pair = $derived(pairSet ? pairs.find((f) => f.s === pairSet[0] && f.u === pairSet[1]) : best);
	const fit = $derived.by(() => {
		if (!drag) return pair;
		const near = nearestInPlane(pair.plane, drag);
		const inplane2 = (drag[0] - near.q[0]) ** 2 + (drag[1] - near.q[1]) ** 2;
		const xx = drag[0] ** 2 + drag[1] ** 2 + pair.h ** 2;
		return { ...pair, p: drag, ...near, inplane2, d2: pair.h ** 2 + inplane2, frac: (pair.h ** 2 + inplane2) / xx, xx };
	});

	// ── layout ─────────────────────────────────────────────────────────────────────
	const triCell = $derived(narrow ? Math.min(52, (W - 34) / 6) : Math.min(50, W * 0.056));
	const triW = $derived(triCell * 6 + 26);
	const leftW = $derived(narrow ? W : W - triW - 34);
	const stripY = 22;
	const stripW = $derived(Math.min(leftW - (interactive ? 150 : 40), 340));
	const top = 58;

	// the 3-D view of span(v_s, v_u, x)
	// The view turns the plane so that the column's nearest point (or its foot, if that is the
	// apex) lies to the right of the apex: the right triangle 0, x_J, x is then seen nearly
	// face on. The view follows the column and the pair, not the dragged foot.
	const beta = 0.6;
	const R = $derived(1.1 * Math.max(pair.plane.a[0], Math.hypot(...pair.plane.b), Math.hypot(...pair.p), Math.hypot(...fit.p), 1e-9));
	const aim = $derived(Math.hypot(...pair.q) > 1e-9 ? pair.q : pair.p);
	const psi = $derived(0.22 - Math.atan2(aim[1], aim[0]));
	const view0 = $derived(axonometric({ psi, beta, scale: 1, ox: 0, oy: 0 }));
	const box = $derived.by(() => {
		const pts = [];
		for (let i = 0; i < 36; i++) pts.push(view0.P(R * Math.cos((i * Math.PI) / 18), R * Math.sin((i * Math.PI) / 18)));
		pts.push(view0.P(fit.p[0], fit.p[1], fit.h));
		const xs = pts.map((z) => z[0]), ys = pts.map((z) => z[1]);
		return { x0: Math.min(...xs), x1: Math.max(...xs), y0: Math.min(...ys), y1: Math.max(...ys) };
	});
	const sc = $derived(Math.min((leftW - 40) / (box.x1 - box.x0), (narrow ? 340 : 400) / (box.y1 - box.y0)));
	const view = $derived(axonometric({ psi, beta, scale: sc, ox: 20 + (leftW - 40 - sc * (box.x1 - box.x0)) / 2 - sc * box.x0, oy: top + 26 - sc * box.y0 }));
	const viewH = $derived(top + 26 + sc * (box.y1 - box.y0) + 30);
	const P2 = $derived((u, v) => view.P(u, v, 0));
	const P3 = $derived(view.P);

	// points of the drawing
	const O = $derived(P3(0, 0, 0));
	const Xs = $derived(P3(fit.p[0], fit.p[1], fit.h));
	const Ps = $derived(P3(fit.p[0], fit.p[1], 0));
	const Qs = $derived(P3(fit.q[0], fit.q[1], 0));
	const A = $derived(pair.plane.a), B = $derived(pair.plane.b);
	const cs = $derived(fit.c[0]), cu = $derived(fit.c[1]);
	const Cs = $derived(P2(cs * A[0], cs * A[1]));
	const Cu = $derived(P2(cu * B[0], cu * B[1]));
	const pol = $derived(polarEdges(pair.plane));
	const CsL = $derived(P2(cs * A[0] + pol.s[0] * R * 0.16, cs * A[1] + pol.s[1] * R * 0.16));
	const CuL = $derived(P2(cu * B[0] + pol.u[0] * R * 0.16, cu * B[1] + pol.u[1] * R * 0.16));
	// right-angle marks: at x_J between −x_J and x − x_J; at p between the plane and the drop
	const eps = $derived(R * 0.075);
	const rightAt = (Q, u1, u2) => {
		const n1 = Math.hypot(...u1) || 1, n2 = Math.hypot(...u2) || 1;
		const a = u1.map((z) => (z / n1) * eps), b = u2.map((z) => (z / n2) * eps);
		const p1 = P3(Q[0] + a[0], Q[1] + a[1], Q[2] + a[2]);
		const p2 = P3(Q[0] + a[0] + b[0], Q[1] + a[1] + b[1], Q[2] + a[2] + b[2]);
		const p3 = P3(Q[0] + b[0], Q[1] + b[1], Q[2] + b[2]);
		return `M${p1[0]} ${p1[1]} L${p2[0]} ${p2[1]} L${p3[0]} ${p3[1]}`;
	};
	const qLen = $derived(Math.hypot(fit.q[0], fit.q[1]));
	const markQ = $derived(qLen > eps * 1.5 && fit.d2 > 1e-9 ? rightAt([fit.q[0], fit.q[1], 0], [-fit.q[0], -fit.q[1], 0], [fit.p[0] - fit.q[0], fit.p[1] - fit.q[1], fit.h]) : '');
	const pq = $derived(Math.hypot(fit.p[0] - fit.q[0], fit.p[1] - fit.q[1]));
	const apart = $derived(pq > R * 0.012); // the foot p is off the cone
	const markP = $derived(fit.h > eps * 1.5 && pq > eps * 1.5 ? rightAt([fit.p[0], fit.p[1], 0], [fit.q[0] - fit.p[0], fit.q[1] - fit.p[1], 0], [0, 0, 1]) : '');
	const mid = (a, b, f = 0.5) => [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f];
	const rLabel = $derived(mid(Qs, Xs, 0.55));

	// the triangle of the 21 pairs
	const triX = $derived(narrow ? (W - triCell * 6) / 2 + 10 : W - triCell * 6 - 4);
	const triY = $derived(narrow ? viewH + 26 : top + 22);
	const triR = $derived(Math.max(...pairs.map((f) => Math.max(f.plane.a[0], Math.hypot(...f.plane.b), Math.hypot(...f.p)))) * 1.04);
	const gk = $derived((triCell * 0.36) / triR);
	const cellView = (f, i, j) => {
		const cx = triX + j * triCell + triCell / 2, cy = triY + (i - 1) * triCell + triCell * 0.42;
		const rot = Math.PI / 2 - f.plane.angle / 2, c = Math.cos(rot), s = Math.sin(rot);
		return (u, v) => [cx + gk * (u * c - v * s), cy - gk * (u * s + v * c)];
	};
	const H = $derived(narrow ? triY + 6 * triCell + 20 : Math.max(viewH, triY + 6 * triCell + 34));

	// ── interaction ────────────────────────────────────────────────────────────────
	let dragging = $state(false);
	function svgPoint(e) {
		const svg = e.currentTarget.ownerSVGElement ?? e.currentTarget.closest('svg');
		const pt = svg.createSVGPoint(); pt.x = e.clientX; pt.y = e.clientY;
		return pt.matrixTransform(svg.getScreenCTM().inverse());
	}
	function setFoot(e) {
		const p = svgPoint(e);
		let u = view.inv(p.x, p.y);
		const r = Math.hypot(u[0], u[1]), rm = R * 0.97;
		if (r > rm) u = [(u[0] * rm) / r, (u[1] * rm) / r];
		drag = u;
	}
	function down(e) { dragging = true; e.currentTarget.setPointerCapture(e.pointerId); setFoot(e); }
	function move(e) { if (dragging) setFoot(e); }
	function up() { dragging = false; }
	function footKey(e) {
		const d = R / 24, p = drag ?? pair.p;
		const m = { ArrowLeft: [-d, 0], ArrowRight: [d, 0], ArrowUp: [0, d], ArrowDown: [0, -d] }[e.key];
		if (m) { drag = [p[0] + m[0], p[1] + m[1]]; e.preventDefault(); }
		if (e.key === 'Escape' || e.key === 'Home') { drag = null; e.preventDefault(); }
	}
	function choosePair(f) { pairSet = [f.s, f.u]; drag = null; }
	$effect(() => { start; pos; depth; drag = null; });

	const chosenWords = $derived(`‘${showChar(tr.chars[pos])}’ at position ${pos + 1} of “${tr.text}”, depth ${depthLabel(depth / 2)}`);
	const pairName = (f) => `(${showChar(vocab[f.s])}, ${showChar(vocab[f.u])})`;
	const pct = (f) => `${fmt(100 * f, 0)}%`;
	// the readout in words; v with its character as a subscript (HTML, our own strings only)
	const vh = (a) => `<i>v</i><sub>${showChar(vocab[a])}</sub>`;
	const readout = $derived.by(() => {
		const f = fit, S = pair.s, U = pair.u;
		const comp = f.region === 'cone' ? `<i>x</i><sub>J</sub> = ${fmt(cs)} ${vh(S)} + ${fmt(cu)} ${vh(U)}, inside the cone`
			: f.region === 'apex' ? `<i>x</i><sub>J</sub> = 0: the column leans away from both vectors, and its nearest point is the apex`
			: `<i>x</i><sub>J</sub> = ${fmt(f.region === 's' ? cs : cu)} ${vh(f.region === 's' ? S : U)}, on that edge of the cone`;
		const rem = `the remainder holds ${pct(f.frac)} of ‖<i>x</i>‖² (${pct(f.h ** 2 / f.xx)} perpendicular to the plane, ${pct(f.inplane2 / f.xx)} within it)`;
		const body = `Pair ${pairName(pair)}: ${comp}; ${rem}.`;
		const bestS = `Best of the ${pairs.length} pairs: ${pairName(best)}, ${pct(best.frac)} left over.`;
		return { who: `${chosenWords}${drag ? ', moved within the plane' : ''}.`, body, best: bestS, plain: `${body} ${bestS}`.replace(/<[^>]+>/g, '') };
	});
	const depthOptions = $derived((js?.depth ?? [0, 0.5, 1]).map((d, j) => ({ value: j, label: depthLabel(d) })));
</script>

<div class="fx fx-cone" use:measure={(w) => (width = w)}>
	{#if js}
		<svg viewBox="0 0 {W} {H}" width={W} height={H} role={interactive ? 'group' : 'img'} aria-label="{chosenWords}. {readout.plain}">
			<!-- the column: corpus strip, and the depth -->
			<CorpusStrip corpus={specimen.corpus} {T} bind:start bind:pos x={20} y={stripY} width={stripW} {interactive} label="the column x" />
			{#if interactive}
				<TickTrack options={depthOptions} bind:value={depth} x={stripW + 78} y={stripY - 5} width={narrow ? 56 : 64} name="depth" />
			{:else}
				<text class="lbl" x={stripW + 34} y={stripY}>depth {depthLabel(depth / 2)}</text>
			{/if}

			<!-- the 3-D view: the plane, the cone, x above it -->
			<g class="fx-cone__view">
				<ConeGlyph plane={pair.plane} {R} P={P2} chars={[vocab[pair.s], vocab[pair.u]]} disc ghost polar hatch={13} tip={2.6} labelSize={narrow ? 13 : 15} />
				<!-- the coordinates of x_J along the edges -->
				{#if fit.region !== 'apex'}
					{#if fit.region === 'cone'}
						<line class="fx-cone__coord" x1={Qs[0]} y1={Qs[1]} x2={Cs[0]} y2={Cs[1]} />
						<line class="fx-cone__coord" x1={Qs[0]} y1={Qs[1]} x2={Cu[0]} y2={Cu[1]} />
					{/if}
					{#each [[cs, Cs, CsL], [cu, Cu, CuL]] as [c, C, CL], k (k)}
						{#if c > 0}
							<circle class="fx-cone__tick" cx={C[0]} cy={C[1]} r="2.4" />
							<text class="lbl lbl--micro fx-cone__clabel" x={CL[0]} y={CL[1] + 4} text-anchor="middle">{fmt(c)}</text>
						{/if}
					{/each}
				{/if}
				<!-- the foot of x, and the drop to it -->
				{#if apart}
					<line class="fx-cone__drop" x1={Xs[0]} y1={Xs[1]} x2={Ps[0]} y2={Ps[1]} />
					{#if markP}<path class="fx-cone__right" d={markP} />{/if}
					<line class="fx-cone__inplane" x1={Ps[0]} y1={Ps[1]} x2={Qs[0]} y2={Qs[1]} />
					<circle class="fx-cone__foot" cx={Ps[0]} cy={Ps[1]} r="3" />
					<text class="fx-cone__m" x={Ps[0] + 7} y={Ps[1] + 13}>p</text>
				{/if}
				<!-- x, x_J and the remainder -->
				<line class="fx-cone__x" x1={O[0]} y1={O[1]} x2={Xs[0]} y2={Xs[1]} />
				{#if qLen > 1e-9}<line class="fx-cone__xj" x1={O[0]} y1={O[1]} x2={Qs[0]} y2={Qs[1]} />{/if}
				<line class="fx-cone__rem" x1={Qs[0]} y1={Qs[1]} x2={Xs[0]} y2={Xs[1]} />
				{#if markQ}<path class="fx-cone__right" d={markQ} />{/if}
				<circle class="fx-cone__dot" cx={Xs[0]} cy={Xs[1]} r="3.6" />
				<circle class="fx-cone__dot" cx={Qs[0]} cy={Qs[1]} r="3.6" />
				<text class="fx-cone__name" x={Xs[0] + 8} y={Xs[1] - 6}>x</text>
				<text class="fx-cone__name" x={Qs[0] + 9} y={Qs[1] + 15}>x<tspan class="fx-cone__sub" dy="4">J</tspan>{#if !apart}<tspan dy="-4"> = </tspan><tspan>p</tspan>{/if}</text>
				<text class="lbl lbl--micro lbl--value" x={rLabel[0] + 7} y={rLabel[1]}>x − x<tspan dy="3" font-size="8">J</tspan></text>
				<text class="lbl lbl--micro" x={O[0] - 6} y={O[1] + 4} text-anchor="end">0</text>
				{#if interactive}
					<circle class="handle" class:handle--active={dragging} cx={Ps[0]} cy={Ps[1]} r="6" style="fill: transparent" />
					<path
						class="handle-hit"
						d={(() => { const pts = Array.from({ length: 49 }, (_, i) => P2(R * Math.cos((i * Math.PI) / 24), R * Math.sin((i * Math.PI) / 24))); return 'M' + pts.map((z) => z.join(' ')).join(' L') + ' Z'; })()}
						role="slider"
						tabindex="0"
						aria-label="the foot p of x in the plane (arrow keys move it; Escape returns it)"
						aria-valuenow={Math.round(100 * fit.frac)}
						aria-valuemin="0"
						aria-valuemax="100"
						aria-valuetext={readout.plain}
						onpointerdown={down}
						onpointermove={move}
						onpointerup={up}
						ondblclick={() => (drag = null)}
						onkeydown={footKey}
					/>
				{/if}
			</g>

			<!-- the 21 pairs -->
			<g class="fx-cone__tri">
				<text class="lbl lbl--head" x={triX - 22} y={triY - 30}>all {pairs.length} pairs, k = 2</text>
				{#each vocab.slice(0, V - 1) as ch, j (j)}
					<text class="tok fx-cone__axis" x={triX + j * triCell + triCell / 2} y={triY - 8} text-anchor="middle">{showChar(ch)}</text>
				{/each}
				{#each vocab.slice(1) as ch, i (i)}
					<text class="tok fx-cone__axis" x={triX - 8} y={triY + i * triCell + triCell * 0.42 + 5} text-anchor="end">{showChar(ch)}</text>
				{/each}
				{#each pairs as f (f.s * 16 + f.u)}
					{@const isSel = f.s === pair.s && f.u === pair.u}
					{@const isBest = f === best}
					{@const cv = cellView(f, f.u, f.s)}
					{@const c0 = cv(0, 0)}
					{#if isSel}<circle class="fx-cone__sel" cx={c0[0]} cy={c0[1] - triCell * 0.05} r={triCell * 0.47} />{/if}
					<ConeGlyph plane={f.plane} R={triR * 0.98} P={cv} hatch={5} tip={1.3} labels={false} p={f.p} q={f.q} strong={isBest} muted={f.frac > 0.999} />
					<text class="lbl lbl--micro fx-cone__frac" class:is-best={isBest} x={c0[0]} y={c0[1] + triCell * 0.5} text-anchor="middle">{fmtDense(f.frac, 2)}</text>
					{#if interactive}
						<rect class="hit" x={c0[0] - triCell / 2} y={c0[1] - triCell * 0.42} width={triCell} height={triCell} role="button" tabindex="0" aria-label="pair {pairName(f)}: {pct(f.frac)} of ‖x‖² left over" onclick={() => choosePair(f)} onkeydown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); choosePair(f); } }} />
					{/if}
				{/each}
				<text class="lbl lbl--micro" x={triX + triCell * 6} y={triY + 6 * triCell + 14} text-anchor="end">share of ‖x‖² left over</text>
			</g>
		</svg>
		{#if interactive}
			<p class="readout" aria-live="polite">
				<span class="readout__who">{readout.who}</span>
				<span class="readout__part">{@html readout.body}</span>
				<span class="readout__part">{readout.best}</span>
				<span class="readout__hint">Click a character for another column, a small cone for another pair; drag the foot p across the plane.</span>
			</p>
		{/if}
	{:else}
		<p class="fig__pending">The J-lens export (jspace/artifacts/specimen-jlens.json) is not available.</p>
	{/if}
</div>

<style>
	.fx-cone__coord { stroke: var(--ink-3); stroke-width: var(--hair); stroke-dasharray: 1.5 2.5; }
	.fx-cone__tick { fill: var(--paper); stroke: var(--ink); stroke-width: 1px; }
	.fx-cone__clabel { fill: var(--ink-2); }
	.fx-cone__drop { stroke: var(--ink-3); stroke-width: var(--hair); stroke-dasharray: 3 2.5; }
	.fx-cone__inplane { stroke: var(--value); stroke-width: var(--hair); stroke-dasharray: 2 2; }
	.fx-cone__right { fill: none; stroke: var(--ink-3); stroke-width: var(--hair); }
	.fx-cone__foot { fill: var(--paper); stroke: var(--value); stroke-width: 1px; }
	.fx-cone__x { stroke: var(--value); stroke-width: var(--line); }
	.fx-cone__xj { stroke: var(--value); stroke-width: var(--heavy); }
	.fx-cone__rem { stroke: var(--value); stroke-width: var(--line); stroke-dasharray: 5 3; }
	.fx-cone__dot { fill: var(--value); }
	.fx-cone__name { font-family: var(--serif); font-style: italic; font-size: 16px; fill: var(--value-deep); }
	.fx-cone__sub { font-size: 11px; font-style: normal; }
	.fx-cone__m { font-family: var(--serif); font-style: italic; font-size: 13px; fill: var(--ink-2); }
	.fx-cone__axis { font-size: 14px; fill: var(--ink-2); }
	.fx-cone__frac { fill: var(--ink-3); }
	.fx-cone__frac.is-best { fill: var(--ink); font-weight: 650; }
	.fx-cone__sel { fill: var(--value-tint); }
	:global([data-mode='print']) .fx-cone__sel { display: none; }
</style>
